head.script:
scwin.onpageload = function() {
	wdc_main.createWindow("TEST1", null, "/sample/common_link/windowContainer_accessibility_WESD-1586_(WSQ-5576)_component3.xml", "TEST1", "TEST1");
	wdc_main.createWindow("TEST2", null, "/sample/common_link/windowContainer_accessibility_WESD-1586_(WSQ-5576)_component4.xml", "TEST2", "TEST2");
};

scwin.checkVal1 = function() {
	const parentDiv = (document.getElementById('wdc_main') || document.getElementById('mf_wdc_main'));
	const childDivs = parentDiv.children;
	let return_check = false;
	if (childDivs.length >= 2) {
		if (childDivs[0].id === 'mf_wdc_main_toolbar' && childDivs[1].id === 'mf_wdc_main_window') {
			return_check = true;
		}
	}
	return return_check;
};
